// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "I have a my apps linux container running at 192.168.100.125. could you remake the app using tanstack and have the state of it persist with a local sqlite database. also use React for the UI with components from: https://www.reactbits.dev/. after you are done could you deploy it onto the container."
// Changes: History tab – named and automatic snapshots stored in SQLite, with create/restore/delete.

// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Shows the snapshot kind (auto / named / safety), wraps full labels, in-page confirm dialogs, a real
//          <form> for saving (IME-safe Enter, respects busy), buttons described by their version, focus after delete.

import { useServerFn } from '@tanstack/react-start'
import { useCallback, useEffect, useId, useLayoutEffect, useRef, useState, type FormEvent } from 'react'
// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
// Changes: Saving a named version and restoring go through the project session (props); delete is keyed by project id.
import { deleteSnapshotFn, listSnapshotsFn } from '#/server/projects.functions'
import type { SnapshotKind, SnapshotSummary } from '#/server/projects.server'
import { useConfirm } from './ConfirmDialog'
import { useToast } from './Toasts'
import { Button, DangerButton, Help, Panel, PrimaryButton, TextInput, cx } from './ui'
import { SplitLayout } from './SplitLayout'

export const formatTime = (iso: string) => new Date(iso).toLocaleString('sk-SK', { dateStyle: 'medium', timeStyle: 'short' })

const KIND: Record<SnapshotKind, { text: string; className: string }> = {
  named: { text: 'Pomenovaná', className: 'bg-indigo-500/15 text-indigo-200' },
  auto: { text: 'Automatická záloha', className: 'bg-white/5 text-zinc-300' },
  safety: { text: 'Pred obnovením/importom', className: 'bg-amber-500/10 text-amber-200' },
}

/** Server-side limit for a version label (LABEL_MAX in projects.server). */
const LABEL_MAX = 200

export function HistoryTab({
  projectId,
  onSaveVersion,
  onRestore,
}: {
  projectId: string
  /** Saves local edits first; rejects with a Slovak message when they cannot be saved. */
  onSaveVersion: (label: string) => Promise<unknown>
  /** Saves local edits first and adopts the restored version; rejects like onSaveVersion. */
  onRestore: (snapshotId: number) => Promise<void>
}) {
  const toast = useToast()
  const confirm = useConfirm()
  const list = useServerFn(listSnapshotsFn)
  const remove = useServerFn(deleteSnapshotFn)
  const [snapshots, setSnapshots] = useState<SnapshotSummary[] | null>(null)
  const [label, setLabel] = useState('')
  const [busy, setBusy] = useState(false)
  const headingRef = useRef<HTMLSpanElement>(null)
  const helpId = useId()
  const itemRefs = useRef(new Map<number, HTMLButtonElement>())
  // After restore/delete (buttons were disabled while busy): the version whose first button gets focus (null = heading).
  const focusAfter = useRef<number | null | undefined>(undefined)

  const reload = useCallback(async () => setSnapshots(await list({ data: { id: projectId } })), [list, projectId])
  useEffect(() => {
    void reload()
  }, [reload])

  useLayoutEffect(() => {
    // Wait until the buttons are enabled again (they are disabled while busy).
    const target = focusAfter.current
    if (target === undefined || busy) return
    focusAfter.current = undefined
    ;((target !== null && itemRefs.current.get(target)) || headingRef.current)?.focus()
  }, [snapshots, busy])

  const run = async (fn: () => Promise<void>, failTitle: string) => {
    setBusy(true)
    try {
      await fn()
    } catch (err) {
      toast({ title: failTitle, description: err instanceof Error ? err.message : String(err), tone: 'bad' })
    } finally {
      setBusy(false)
    }
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
  // Changes: No "Verzia uložená" unless local edits were saved first (the session rejects otherwise → error toast).
  const save = (e: FormEvent) => {
    e.preventDefault()
    if (busy) return
    void run(async () => {
      await onSaveVersion(label.trim() || `Verzia ${new Date().toLocaleString('sk-SK')}`)
      setLabel('')
      await reload()
      toast({ title: 'Verzia uložená', tone: 'ok' })
    }, 'Verziu sa nepodarilo uložiť')
  }

  const restore = async (s: SnapshotSummary) => {
    const ok = await confirm({
      title: 'Obnoviť verziu?',
      body: (
        <>
          Obnoví sa verzia „{s.label}“ ({formatTime(s.createdAt)}). Aktuálny stav sa najprv uloží do histórie.
        </>
      ),
      confirmLabel: 'Obnoviť',
    })
    if (!ok) return
    // AI generated by: Claude Code / claude-opus-5-5
    // Prompt: "ok its looks good i agree with the findings, now i want you to dig into the problem and implement the changes"
    // Changes: Restore through the session – refuses while local edits are unsaved or in conflict.
    await run(async () => {
      await onRestore(s.id)
      focusAfter.current = s.id
      await reload()
      toast({ title: 'Verzia obnovená', description: s.label, tone: 'ok' })
    }, 'Obnovenie zlyhalo')
  }

  const del = async (s: SnapshotSummary, index: number) => {
    const ok = await confirm({
      title: 'Zmazať verziu?',
      body: <>Verzia „{s.label}“ ({formatTime(s.createdAt)}) sa natrvalo odstráni.</>,
      confirmLabel: 'Zmazať',
      tone: 'danger',
    })
    if (!ok || !snapshots) return
    const neighbour = snapshots[index + 1] ?? snapshots[index - 1]
    await run(async () => {
      await remove({ data: { id: projectId, snapshotId: s.id } })
      focusAfter.current = neighbour ? neighbour.id : null
      await reload()
    }, 'Mazanie zlyhalo')
  }

  // AI generated by: Claude Code / claude-opus-5-5
  // Prompt: "Make the two sections left and right resizable"
  // Changes: Resizable two-column layout.
  return (
    <SplitLayout>
      <Panel title="Uložiť verziu">
        <form onSubmit={save}>
          <TextInput
            value={label}
            placeholder="napr. Pred zmenou výrazov"
            onChange={(e) => setLabel(e.target.value)}
            maxLength={LABEL_MAX}
            enterKeyHint="done"
            aria-label="Popis verzie"
            aria-describedby={helpId}
          />
          <div className="mt-3">
            <PrimaryButton type="submit" disabled={busy}>
              Uložiť verziu
            </PrimaryButton>
          </div>
        </form>
        <Help>
          <span id={helpId}>
            Pri úpravách sa najviac raz za 20 minút uloží aj automatická záloha (posledných 30). Pred obnovením alebo importom
            sa aktuálny stav vždy odloží sem.
          </span>
        </Help>
      </Panel>

      <Panel
        title={
          <span ref={headingRef} tabIndex={-1} className="rounded focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-400">
            História
          </span>
        }
      >
        {snapshots === null ? (
          <div className="text-sm text-zinc-400">Načítavam…</div>
        ) : snapshots.length === 0 ? (
          <div className="text-sm text-zinc-400">Zatiaľ žiadne uložené verzie.</div>
        ) : (
          <ul className="divide-y divide-white/5">
            {snapshots.map((s, i) => {
              const labelId = `snapshot-${s.id}-label`
              const kind = KIND[s.kind]
              return (
                <li key={s.id} className="flex flex-wrap items-center gap-3 py-2.5">
                  <div className="min-w-0 flex-1">
                    {/* Full label, wrapped (no truncation that would hide part of it). */}
                    <div id={labelId} className="text-sm text-zinc-200 [overflow-wrap:anywhere]">
                      {s.label}
                    </div>
                    <div className="mt-0.5 flex flex-wrap items-center gap-2 text-xs text-zinc-400">
                      {formatTime(s.createdAt)}
                      <span className={cx('rounded-full px-2 py-0.5 text-[11px]', kind.className)}>{kind.text}</span>
                    </div>
                  </div>
                  <Button
                    ref={(el) => {
                      if (el) itemRefs.current.set(s.id, el)
                      else itemRefs.current.delete(s.id)
                    }}
                    disabled={busy}
                    aria-describedby={labelId}
                    onClick={() => void restore(s)}
                  >
                    Obnoviť
                  </Button>
                  <DangerButton disabled={busy} aria-describedby={labelId} onClick={() => void del(s, i)}>
                    Zmazať
                  </DangerButton>
                </li>
              )
            })}
          </ul>
        )}
      </Panel>
    </SplitLayout>
  )
}
